export function UnsupportedCard({
  resource,
  className,
  bare,
  message,
  showDownload = true,
}: {
  resource: ViewerResource;
  className?: string;
  bare?: boolean;
  message?: string;
  showDownload?: boolean;
}) {
  return (
    <FileViewerUnsupportedState
      className={cn(
        bare ? "bg-muted/20 h-full" : "bg-muted/30 min-h-64 rounded-xl border",
        className,
