export function ViewerSidebarTrigger({
  className,
  disabled,
  loading,
  onClick,
  onPointerDown,
  children,
  size = "icon",
  variant = "ghost",
  "aria-label": ariaLabel = "Toggle sidebar",
  "aria-disabled": ariaDisabled,
  ...props
}: ViewerSidebarTriggerProps) {
  const {
    hasSidebar,
    sidebarState,
    rootId,
    sidebarId,
    sidebarSide,
    setLastTriggerElement,
  } = useViewerSidebarRegistrationContext("ViewerSidebarTrigger");
  const { canToggleSidebar, open, state, toggleSidebar } = sidebarState;
  const isDisabled = Boolean(
    disabled || loading || isAriaDisabled(ariaDisabled) || !canToggleSidebar,
  );
  const Icon = sidebarSide === "right" ? PanelRight : PanelLeft;

  return (
    <Button
      aria-controls={hasSidebar ? sidebarId : undefined}
      aria-disabled={isDisabled ? true : ariaDisabled}
      aria-expanded={hasSidebar ? open : undefined}
      aria-label={ariaLabel}
      className={cn("size-8", className)}
      data-side={sidebarSide}
      data-slot="viewer-sidebar-trigger"
      data-state={state}
      data-viewer-root-id={rootId}
      data-viewer-sidebar-trigger=""
      disabled={isDisabled}
      onClick={(event) => {
        setLastTriggerElement(event.currentTarget);
        if (isDisabled) {
          event.preventDefault();
          return;
        }

        onClick?.(event);
        if (!event.defaultPrevented) {
          toggleSidebar();
        }
      }}
      onPointerDown={(event) => {
        setLastTriggerElement(event.currentTarget);
        onPointerDown?.(event);
      }}
      size={size}
      variant={variant}
      {...props}
    >
      {loading ? <Spinner className="size-4 animate-spin" /> : null}
      {children ?? (
        <>
          {loading ? null : <Icon />}
          <span className="sr-only">Toggle sidebar</span>
        </>
      )}
    </Button>
  );
}

"use client";

const emittedViewerDevelopmentWarnings = new Set<string>();

export type ViewerDevelopmentWarningDetails = Record<string, unknown>;

export function warnViewerDevelopmentOnce({
  code,
  details,
  message,
  rootId,
}: {
  code: string;
  details?: ViewerDevelopmentWarningDetails;
  message: string;
  rootId: string;
}) {
  if (process.env.NODE_ENV === "production") return;

  const warningKey = `${rootId}:${code}`;
  if (emittedViewerDevelopmentWarnings.has(warningKey)) return;
  emittedViewerDevelopmentWarnings.add(warningKey);

  console.warn(`[file-viewer] ${message}`, {
    code,
    rootId,
    ...details,
  });
}

export function resetViewerDevelopmentWarningsForTests() {
  emittedViewerDevelopmentWarnings.clear();
}

